<?php
require_once __DIR__.'/includes/auth.php';require_login();$pdo=db();$staff=current_user()['role']!=='resident';
if($_SERVER['REQUEST_METHOD']==='POST'&&$staff){verify_csrf();$action=$_POST['form_action']??'';$id=(int)($_POST['id']??0);if($action==='save'){ $title=trim($_POST['title']??'');$body=trim($_POST['body']??'');$category=trim($_POST['category']??'Community');$draft=isset($_POST['is_draft'])?1:0;if($title===''||$body===''){flash('error','Title and announcement body are required.');redirect('announcements.php?action=new');}if($id){$pdo->prepare('UPDATE announcements SET title=?,body=?,category=?,is_draft=?,is_published=?,archived_at=NULL WHERE id=?')->execute([$title,$body,$category,$draft,$draft?0:1,$id]);audit_action('announcement_updated','announcements',$id,$title);}else{$pdo->prepare('INSERT INTO announcements (title,body,category,is_draft,is_published) VALUES (?,?,?,?,?)')->execute([$title,$body,$category,$draft,$draft?0:1]);audit_action('announcement_created','announcements',(int)$pdo->lastInsertId(),$title);}flash('success',$draft?'Announcement saved as draft.':'Announcement published.');redirect('announcements.php');}if(in_array($action,['publish','unpublish','archive'],true)){if($action==='archive')$pdo->prepare('UPDATE announcements SET archived_at=NOW(),is_published=0,is_draft=0 WHERE id=?')->execute([$id]);else $pdo->prepare('UPDATE announcements SET is_published=?,is_draft=0,archived_at=NULL WHERE id=?')->execute([$action==='publish'?1:0,$id]);audit_action('announcement_'.$action,'announcements',$id);flash('success','Announcement lifecycle status updated.');redirect('announcements.php');}}
$edit=null;if($staff&&isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM announcements WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$items=$staff?$pdo->query('SELECT * FROM announcements ORDER BY COALESCE(archived_at,published_at) DESC,id DESC')->fetchAll():$pdo->query('SELECT * FROM announcements WHERE is_published=1 AND is_draft=0 AND archived_at IS NULL ORDER BY published_at DESC')->fetchAll();$pageTitle='Announcements';$activePage='announcements';require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow"><?= $staff?'Community / Information desk':'Resident portal / Community desk' ?></div><h1>Barangay announcements</h1><p>Publish clear updates, keep drafts private, and preserve an audit trail for every lifecycle change.</p></div><?php if($staff): ?><a class="primary-button" href="announcements.php?action=new">＋ New announcement</a><?php endif; ?></section><?php if($staff&&($_GET['action']??'')==='new'||$edit): ?><section class="panel form-panel"><div class="card-header"><h2><?= $edit?'Edit announcement':'New announcement' ?></h2><a class="text-button" href="announcements.php">Close ×</a></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="form_action" value="save"><input type="hidden" name="id" value="<?= h($edit['id']??'') ?>"><label>Title<input name="title" required value="<?= h($edit['title']??'') ?>"></label><label>Category<input name="category" required value="<?= h($edit['category']??'Community') ?>"></label><label class="wide">Announcement body<textarea name="body" rows="5" required><?= h($edit['body']??'') ?></textarea></label><label class="check-field"><input type="checkbox" name="is_draft" <?= !empty($edit['is_draft'])?'checked':'' ?>> Save as draft (not visible to residents)</label><div class="form-actions"><a class="secondary-button" href="announcements.php">Cancel</a><button class="primary-button">Save announcement</button></div></form></section><?php endif; ?><div class="announcement-card-grid"><?php foreach($items as $item): ?><article class="panel announcement-card"><div class="announcement-banner <?= h(strtolower($item['category'])) ?>"><span><?= h($item['category']) ?></span><small><?= $item['archived_at']?'Archived':($item['is_draft']?'Draft':($item['is_published']?'Published':'Unpublished')) ?> · <?= h(date('M d, Y',strtotime($item['published_at']))) ?></small></div><div class="announcement-card-body"><div class="eyebrow"><?= $staff?'Lifecycle-managed update':'Published update' ?></div><h3><?= h($item['title']) ?></h3><p><?= nl2br(h($item['body'])) ?></p><?php if($staff): ?><div class="request-actions"><a class="text-button" href="announcements.php?edit=<?= h($item['id']) ?>">Edit</a><?php if(!$item['archived_at']): ?><?php if($item['is_published']): ?><form method="post" class="inline-form" onsubmit="return confirm('Unpublish this announcement?')"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="form_action" value="unpublish"><input type="hidden" name="id" value="<?= h($item['id']) ?>"><button class="text-button">Unpublish</button></form><?php else: ?><form method="post" class="inline-form" onsubmit="return confirm('Publish this announcement now?')"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="form_action" value="publish"><input type="hidden" name="id" value="<?= h($item['id']) ?>"><button class="text-button">Publish</button></form><?php endif; ?><form method="post" class="inline-form" onsubmit="return confirm('Archive this announcement?')"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="form_action" value="archive"><input type="hidden" name="id" value="<?= h($item['id']) ?>"><button class="text-button">Archive</button></form><?php endif; ?></div><?php endif; ?></div></article><?php endforeach; ?><?php if(!$items): ?><p class="empty-state">No announcements are available.</p><?php endif; ?></div><?php require __DIR__.'/partials/footer.php'; ?>
